contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single-entry property test
    function run(address initVADER, address initUSDV, address initVAULT) public payable {
        // require nonzero addresses so init does not revert
        require(initVADER != address(0) && initUSDV != address(0) && initVAULT != address(0));

        // call init exactly once
        c.init(initVADER, initUSDV, initVAULT); if (__ESBMC_reverted()) return;

        // read publicly visible state
        address gotVADER = c.VADER(); if (__ESBMC_reverted()) return;
        address gotUSDV = c.USDV(); if (__ESBMC_reverted()) return;
        address gotVAULT = c.VAULT(); if (__ESBMC_reverted()) return;
        uint gotCool = c.coolOffPeriod(); if (__ESBMC_reverted()) return;

        // General rule: after init, the stored addresses match the inputs and coolOffPeriod > 0
        assert(gotVADER == initVADER && gotUSDV == initUSDV && gotVAULT == initVAULT && gotCool > 0);
    }

    receive() external payable {}
}

